WITH x4 AS (SELECT 1 UNION SELECT x3.v230356 + 1 FROM x6) SELECT x3.v230356 + 60, 0.8 + CAST('a' AS DECIMAL), ST_ASTEXT(ST_DIFFERENCE(ST_GEOMFROMTEXT('MULTILinestring((4 4,4 6,6 6,6 4),(0 0,0 10,10 10,10 0))'), ST_GEOMFROMTEXT('GEOMETRYCOLLECTION(GEOMETRYCOLLECTION(GEOMETRYCOLLECTION()))'))) AS x0, GREATEST(CAST('01-01-01' AS DATE), '01-01-02') + 0.00 FROM v230355 AS x3 WHERE NOT x3.v230356 BETWEEN 4 AND 2